"""Science section + metadata for the Mental Rotation page, all 43 markets.

WHY THIS FILE EXISTS
generate_pages() clones the ENGLISH page into every market, so a new test always
lands with English body prose everywhere. check_untranslated.py catches it and
blocks the deploy - which is how this file came to exist rather than an English
science section quietly shipping to 42 markets.

HOW TO RUN
  cd websites/coreskillai.com && python3 _build/rotation_page.py
Then re-run _build/check_untranslated.py until it exits 0.

Per language the list is:
  [0] <title>
  [1] meta description
  [2] h2   - science heading
  [3] p1   - what mental rotation is
  [4] h3   - why the foils are mirrors
  [5] p2   - the chirality explanation
  [6] q1   - "Does practice help?"
  [7] a1
  [8] q2   - "Why 20 figures?"
  [9] a2
"""
import os, sys, io, re
sys.path.insert(0, os.path.join(os.getcwd(), '_build'))
import tools as T

K = {
"en": ["Mental Rotation Test &#8212; Free Spatial Reasoning Test | CoreSkillAI","20 spatial puzzles: which figure is the same shape, rotated? Measures mental rotation, a core spatial ability. Free, no sign-up, fresh figures every attempt.","The Science Behind Mental Rotation","Mental rotation is the ability to picture an object turning and judge how it would look from a new angle. Shepard and Metzler showed in 1971 that the time people need rises almost linearly with the angle they must rotate through, which is why it is treated as evidence of a real internal transformation rather than a guess. It is one of the clearest markers of spatial ability, a factor that sits apart from verbal and numerical reasoning.","Why every wrong answer is a mirror image","Each incorrect option is the target figure reflected, not a different shape. That matters: if the foils were simply other shapes you could solve every item by counting squares, and the task would measure attention instead of rotation. A reflected figure can never be produced by turning the original in the plane, so telling them apart requires actually rotating it in your head. Every figure is checked to be asymmetric before use, because a symmetric shape is identical to its own mirror image and would have no single right answer.","Does practice help?","Yes, more than for most cognitive tasks. Spatial skill responds well to training and the gains carry over to related spatial problems, though not to unrelated abilities.","Why 20 figures?","Enough to cover both small and large rotations so the score reflects the full range, while keeping the test to about six minutes. Figures are built fresh each attempt, so there is no answer key to memorise."],
"af": ["Geestelike Rotasietoets &#8212; Gratis Ruimtelike Redenasietoets | CoreSkillAI","20 ruimtelike raaisels: watter figuur is dieselfde vorm, gedraai? Meet geestelike rotasie, 'n kernruimtelike vermoë. Gratis, geen registrasie, nuwe figure elke keer.","Die Wetenskap Agter Geestelike Rotasie","Geestelike rotasie is die vermoë om 'n voorwerp te verbeel wat draai en te oordeel hoe dit uit 'n nuwe hoek sou lyk. Shepard en Metzler het in 1971 gewys dat die tyd wat mense nodig het amper lineêr styg met die hoek waardeur hulle moet draai, en daarom word dit as bewys van 'n werklike innerlike transformasie beskou eerder as raaiwerk. Dit is een van die duidelikste merkers van ruimtelike vermoë, 'n faktor wat apart staan van verbale en numeriese redenasie.","Waarom elke verkeerde antwoord 'n spieëlbeeld is","Elke verkeerde opsie is die teikenfiguur weerkaats, nie 'n ander vorm nie. Dit maak saak: as die lokvalle bloot ander vorms was, kon jy elke item oplos deur blokkies te tel, en die taak sou aandag eerder as rotasie meet. 'n Weerkaatste figuur kan nooit deur die oorspronklike in die vlak te draai geskep word nie, dus vereis dit werklike rotasie in jou kop. Elke figuur word vooraf as asimmetries nagegaan, want 'n simmetriese vorm is identies aan sy eie spieëlbeeld en sou geen enkele regte antwoord hê nie.","Help oefening?","Ja, meer as by die meeste kognitiewe take. Ruimtelike vaardigheid reageer goed op oefening en die winste dra oor na verwante ruimtelike probleme, maar nie na onverwante vermoëns nie.","Waarom 20 figure?","Genoeg om klein sowel as groot rotasies te dek sodat die telling die volle reeks weerspieël, terwyl die toets tot ongeveer ses minute beperk bly. Figure word elke keer nuut gebou, so daar is geen antwoordsleutel om te memoriseer nie."],
"ar": ["اختبار الدوران الذهني &#8212; اختبار مجاني للاستدلال المكاني | CoreSkillAI","٢٠ لغزًا مكانيًا: أي شكل هو الشكل نفسه بعد التدوير؟ يقيس الدوران الذهني، وهو قدرة مكانية أساسية. مجاني، بلا تسجيل، وأشكال جديدة في كل محاولة.","العلم وراء الدوران الذهني","الدوران الذهني هو القدرة على تخيل جسم وهو يدور والحكم على شكله من زاوية جديدة. أظهر شيبارد وميتزلر عام ١٩٧١ أن الزمن اللازم يرتفع خطيًا تقريبًا مع الزاوية التي يجب الدوران خلالها، ولهذا يُعد دليلًا على تحوّل داخلي فعلي لا على تخمين. وهو من أوضح مؤشرات القدرة المكانية، وهي عامل مستقل عن الاستدلال اللفظي والعددي.","لماذا كل إجابة خاطئة صورة مرآوية","كل خيار خاطئ هو الشكل المرجعي منعكسًا، لا شكلًا مختلفًا. وهذا مهم: لو كانت المشتتات أشكالًا أخرى لأمكن حل كل سؤال بعدّ المربعات، ولقاس الاختبار الانتباه بدل الدوران. الشكل المنعكس لا يمكن الحصول عليه بتدوير الأصل في المستوى، لذا يتطلب التمييز بينهما تدويرًا فعليًا في الذهن. ويُتحقق من عدم تناظر كل شكل قبل استخدامه، لأن الشكل المتناظر يطابق صورته المرآوية ولن يكون له جواب واحد صحيح.","هل يفيد التدريب؟","نعم، أكثر من معظم المهام المعرفية. تستجيب المهارة المكانية للتدريب جيدًا، وتنتقل المكاسب إلى مسائل مكانية قريبة، لا إلى قدرات غير مرتبطة.","لماذا ٢٠ شكلًا؟","عدد يكفي لتغطية الدورات الصغيرة والكبيرة معًا كي تعكس الدرجة المدى كاملًا، مع إبقاء الاختبار في نحو ست دقائق. تُبنى الأشكال من جديد في كل محاولة، فلا يوجد مفتاح إجابات يُحفظ."],
"bg": ["Тест за мислено въртене &#8212; безплатен тест за пространствено мислене | CoreSkillAI","20 пространствени задачи: коя фигура е същата форма, само завъртяна? Измерва мисленото въртене, основна пространствена способност. Безплатно, без регистрация, нови фигури всеки път.","Науката зад мисленото въртене","Мисленото въртене е способността да си представите как един обект се завърта и да прецените как би изглеждал под нов ъгъл. Шепард и Мецлер показват през 1971 г., че необходимото време нараства почти линейно с ъгъла, през който трябва да завъртите — затова се приема за доказателство за реално вътрешно преобразуване, а не за догадка. Това е един от най-ясните маркери на пространствената способност, фактор, отделен от словесното и числовото мислене.","Защо всеки грешен отговор е огледален образ","Всяка неправилна възможност е целевата фигура, отразена в огледало, а не друга форма. Това е важно: ако разсейващите бяха просто други фигури, всяка задача би се решавала с броене на квадратчета и тестът щеше да мери внимание, а не въртене. Отразената фигура никога не може да се получи чрез завъртане на оригинала в равнината, затова разграничаването изисква истинско въртене наум. Всяка фигура се проверява за асиметрия преди употреба, защото симетричната форма съвпада със собствения си огледален образ и не би имала един верен отговор.","Помага ли упражнението?","Да, повече отколкото при повечето когнитивни задачи. Пространственото умение се поддава на трениране и напредъкът се пренася върху сродни пространствени задачи, но не и върху несвързани способности.","Защо 20 фигури?","Достатъчно, за да обхванат както малки, така и големи завъртания, така че резултатът да отразява целия обхват, а тестът да остане около шест минути. Фигурите се създават наново при всеки опит, така че няма ключ с отговори за запомняне."],
"cs": ["Test mentální rotace &#8212; bezplatný test prostorového uvažování | CoreSkillAI","20 prostorových úloh: který obrazec je týž tvar, jen otočený? Měří mentální rotaci, základní prostorovou schopnost. Zdarma, bez registrace, nové obrazce při každém pokusu.","Věda za mentální rotací","Mentální rotace je schopnost představit si otáčející se předmět a posoudit, jak by vypadal z nového úhlu. Shepard a Metzler v roce 1971 ukázali, že potřebný čas roste téměř lineárně s úhlem, o který je třeba otočit — proto se to považuje za doklad skutečné vnitřní transformace, ne za odhad. Je to jeden z nejjasnějších ukazatelů prostorové schopnosti, faktoru odlišného od slovního i číselného uvažování.","Proč je každá špatná odpověď zrcadlovým obrazem","Každá nesprávná možnost je cílový obrazec zrcadlově převrácený, nikoli jiný tvar. Na tom záleží: kdyby byly rozptylovače prostě jiné tvary, dala by se každá úloha vyřešit počítáním čtverečků a test by měřil pozornost místo rotace. Zrcadlený obrazec nelze získat otáčením originálu v rovině, takže rozlišení vyžaduje skutečné otáčení v hlavě. Každý obrazec se před použitím kontroluje na asymetrii, protože symetrický tvar je totožný se svým zrcadlovým obrazem a neměl by jediné správné řešení.","Pomáhá trénink?","Ano, více než u většiny kognitivních úloh. Prostorová dovednost na trénink dobře reaguje a zisky se přenášejí na příbuzné prostorové problémy, nikoli však na nesouvisející schopnosti.","Proč 20 obrazců?","Dost na pokrytí malých i velkých otočení, aby skóre odráželo celý rozsah, a přitom se test vejde do zhruba šesti minut. Obrazce vznikají při každém pokusu znovu, takže není co memorovat."],
"da": ["Mental rotationstest &#8212; gratis test i rumlig tænkning | CoreSkillAI","20 rumlige opgaver: hvilken figur er samme form, bare drejet? Måler mental rotation, en central rumlig evne. Gratis, ingen tilmelding, nye figurer hver gang.","Videnskaben bag mental rotation","Mental rotation er evnen til at forestille sig en genstand dreje og vurdere, hvordan den ville se ud fra en ny vinkel. Shepard og Metzler viste i 1971, at den tid folk skal bruge, stiger næsten lineært med den vinkel, de skal dreje igennem, og derfor betragtes det som tegn på en reel indre transformation frem for et gæt. Det er en af de tydeligste markører for rumlig evne, en faktor der står adskilt fra sproglig og numerisk ræsonnering.","Derfor er alle forkerte svar spejlbilleder","Hver forkert mulighed er målfiguren spejlvendt, ikke en anden form. Det betyder noget: hvis distraktorerne blot var andre former, kunne man løse hver opgave ved at tælle felter, og opgaven ville måle opmærksomhed i stedet for rotation. En spejlvendt figur kan aldrig fremstilles ved at dreje originalen i planet, så at skelne dem kræver reel rotation i hovedet. Hver figur kontrolleres for asymmetri før brug, fordi en symmetrisk form er identisk med sit eget spejlbillede og ikke ville have ét rigtigt svar.","Hjælper træning?","Ja, mere end ved de fleste kognitive opgaver. Rumlige færdigheder reagerer godt på træning, og gevinsterne overføres til beslægtede rumlige problemer, men ikke til urelaterede evner.","Hvorfor 20 figurer?","Nok til at dække både små og store drejninger, så scoren afspejler hele spændet, mens testen holdes på omkring seks minutter. Figurerne bygges nye hver gang, så der er ingen facitliste at huske."],
"de": ["Test zur mentalen Rotation &#8212; kostenloser Test des räumlichen Denkens | CoreSkillAI","20 räumliche Aufgaben: Welche Figur ist dieselbe Form, nur gedreht? Misst mentale Rotation, eine zentrale räumliche Fähigkeit. Kostenlos, ohne Anmeldung, jedes Mal neue Figuren.","Die Wissenschaft hinter der mentalen Rotation","Mentale Rotation ist die Fähigkeit, sich ein Objekt drehend vorzustellen und zu beurteilen, wie es aus einem neuen Winkel aussähe. Shepard und Metzler zeigten 1971, dass die benötigte Zeit nahezu linear mit dem Drehwinkel steigt — deshalb gilt dies als Beleg für eine tatsächliche innere Transformation und nicht für Raten. Es ist einer der klarsten Marker räumlicher Fähigkeit, eines Faktors, der von sprachlichem und numerischem Denken getrennt ist.","Warum jede falsche Antwort ein Spiegelbild ist","Jede falsche Option ist die Zielfigur gespiegelt, keine andere Form. Das ist wichtig: Wären die Ablenker einfach andere Formen, ließe sich jede Aufgabe durch Kästchenzählen lösen, und der Test würde Aufmerksamkeit statt Rotation messen. Eine gespiegelte Figur lässt sich niemals durch Drehen des Originals in der Ebene erzeugen, das Unterscheiden erfordert also echtes Drehen im Kopf. Jede Figur wird vor der Verwendung auf Asymmetrie geprüft, denn eine symmetrische Form ist mit ihrem eigenen Spiegelbild identisch und hätte keine eindeutige Lösung.","Hilft Übung?","Ja, mehr als bei den meisten kognitiven Aufgaben. Räumliche Fertigkeit spricht gut auf Training an, und die Gewinne übertragen sich auf verwandte räumliche Probleme, nicht aber auf unverwandte Fähigkeiten.","Warum 20 Figuren?","Genug, um kleine wie große Drehungen abzudecken, damit der Wert die ganze Bandbreite abbildet, und der Test bleibt bei etwa sechs Minuten. Die Figuren entstehen bei jedem Versuch neu, es gibt also nichts auswendig zu lernen."],
"el": ["Τεστ νοερής περιστροφής &#8212; δωρεάν τεστ χωρικής σκέψης | CoreSkillAI","20 χωρικά ερωτήματα: ποιο σχήμα είναι το ίδιο, μόνο περιστραμμένο; Μετρά τη νοερή περιστροφή, βασική χωρική ικανότητα. Δωρεάν, χωρίς εγγραφή, νέα σχήματα κάθε φορά.","Η επιστήμη πίσω από τη νοερή περιστροφή","Η νοερή περιστροφή είναι η ικανότητα να φαντάζεσαι ένα αντικείμενο να στρέφεται και να κρίνεις πώς θα φαινόταν από νέα γωνία. Οι Shepard και Metzler έδειξαν το 1971 ότι ο χρόνος που χρειάζονται οι άνθρωποι αυξάνεται σχεδόν γραμμικά με τη γωνία περιστροφής, γι' αυτό θεωρείται ένδειξη πραγματικού εσωτερικού μετασχηματισμού και όχι εικασίας. Είναι ένας από τους σαφέστερους δείκτες χωρικής ικανότητας, παράγοντα ξεχωριστού από τη λεκτική και την αριθμητική σκέψη.","Γιατί κάθε λάθος απάντηση είναι κατοπτρική","Κάθε λανθασμένη επιλογή είναι το σχήμα-στόχος κατοπτρισμένο, όχι διαφορετικό σχήμα. Αυτό έχει σημασία: αν οι παραπλανητικές επιλογές ήταν απλώς άλλα σχήματα, θα λύνατε κάθε ερώτημα μετρώντας τετράγωνα και η δοκιμασία θα μετρούσε προσοχή αντί για περιστροφή. Ένα κατοπτρισμένο σχήμα δεν προκύπτει ποτέ από περιστροφή του αρχικού στο επίπεδο, οπότε η διάκριση απαιτεί πραγματική περιστροφή στο μυαλό. Κάθε σχήμα ελέγχεται για ασυμμετρία πριν χρησιμοποιηθεί, γιατί ένα συμμετρικό σχήμα ταυτίζεται με το κάτοπτρό του και δεν θα είχε μία σωστή απάντηση.","Βοηθά η εξάσκηση;","Ναι, περισσότερο από ό,τι στις περισσότερες γνωστικές δοκιμασίες. Η χωρική δεξιότητα ανταποκρίνεται καλά στην εξάσκηση και τα οφέλη μεταφέρονται σε συγγενή χωρικά προβλήματα, όχι όμως σε άσχετες ικανότητες.","Γιατί 20 σχήματα;","Αρκετά για να καλύψουν μικρές και μεγάλες περιστροφές ώστε η βαθμολογία να αποτυπώνει όλο το εύρος, κρατώντας το τεστ γύρω στα έξι λεπτά. Τα σχήματα δημιουργούνται εκ νέου κάθε φορά, οπότε δεν υπάρχει κλειδί να απομνημονεύσετε."],
"es": ["Test de rotación mental &#8212; test gratuito de razonamiento espacial | CoreSkillAI","20 puzles espaciales: ¿qué figura es la misma forma, girada? Mide la rotación mental, una capacidad espacial fundamental. Gratis, sin registro, figuras nuevas en cada intento.","La ciencia de la rotación mental","La rotación mental es la capacidad de imaginar un objeto girando y juzgar cómo se vería desde otro ángulo. Shepard y Metzler mostraron en 1971 que el tiempo necesario crece casi linealmente con el ángulo que hay que girar, por lo que se considera prueba de una transformación interna real y no de una conjetura. Es uno de los marcadores más claros de la capacidad espacial, un factor distinto del razonamiento verbal y numérico.","Por qué toda respuesta incorrecta es una imagen especular","Cada opción incorrecta es la figura objetivo reflejada, no otra forma. Esto importa: si los distractores fueran simplemente otras formas, cada ítem se resolvería contando cuadros y la tarea mediría atención en lugar de rotación. Una figura reflejada nunca puede obtenerse girando la original en el plano, así que distinguirlas exige rotarla de verdad en la mente. Cada figura se comprueba asimétrica antes de usarse, porque una forma simétrica es idéntica a su propio reflejo y no tendría una única respuesta correcta.","¿Sirve practicar?","Sí, más que en la mayoría de tareas cognitivas. La habilidad espacial responde bien al entrenamiento y las mejoras se transfieren a problemas espaciales relacionados, aunque no a capacidades ajenas.","¿Por qué 20 figuras?","Suficientes para cubrir giros pequeños y grandes, de modo que la puntuación refleje todo el rango, manteniendo el test en unos seis minutos. Las figuras se generan de nuevo en cada intento, así que no hay plantilla que memorizar."],
"et": ["Vaimse pöörlemise test &#8212; tasuta ruumilise mõtlemise test | CoreSkillAI","20 ruumilist ülesannet: milline kujund on sama, ainult pööratud? Mõõdab vaimset pöörlemist, keskset ruumilist võimet. Tasuta, registreerimiseta, iga kord uued kujundid.","Vaimse pöörlemise teadus","Vaimne pöörlemine on võime kujutleda eset pöörlemas ja hinnata, milline see uue nurga alt paistaks. Shepard ja Metzler näitasid 1971. aastal, et vajalik aeg kasvab peaaegu lineaarselt pöördenurgaga — seetõttu peetakse seda tõendiks tegelikust sisemisest teisendusest, mitte oletusest. See on üks selgemaid ruumilise võime näitajaid, mis on eraldiseisev sõnalisest ja arvulisest arutlusest.","Miks iga vale vastus on peegelpilt","Iga vale variant on sihtkujund peegeldatuna, mitte teine kujund. See on oluline: kui eksitajad oleksid lihtsalt teised kujundid, saaks iga ülesande lahendada ruute lugedes ja test mõõdaks tähelepanu, mitte pöörlemist. Peegeldatud kujundit ei saa kunagi tekitada originaali tasapinnal pöörates, seega nõuab eristamine tegelikku pööramist peas. Iga kujundit kontrollitakse enne kasutamist asümmeetria suhtes, sest sümmeetriline kujund on identne oma peegelpildiga ja sel poleks üht õiget vastust.","Kas harjutamine aitab?","Jah, rohkem kui enamiku kognitiivsete ülesannete puhul. Ruumiline oskus reageerib treeningule hästi ja võit kandub üle seotud ruumiülesannetele, kuid mitte mitteseotud võimetele.","Miks 20 kujundit?","Piisavalt, et katta nii väikesed kui suured pöörded, nii et tulemus peegeldab kogu ulatust, hoides testi umbes kuue minuti sees. Kujundid luuakse iga katse jaoks uuesti, nii et pole midagi pähe õppida."],
"fa": ["آزمون چرخش ذهنی &#8212; آزمون رایگان استدلال فضایی | CoreSkillAI","۲۰ معمای فضایی: کدام شکل همان شکل است، فقط چرخیده؟ چرخش ذهنی را می‌سنجد که توانایی فضایی بنیادی است. رایگان، بدون ثبت‌نام، با شکل‌های تازه در هر بار.","دانش پشت چرخش ذهنی","چرخش ذهنی توانایی تجسم چرخیدن یک شیء و داوری دربارهٔ ظاهر آن از زاویه‌ای تازه است. شپرد و متزلر در ۱۹۷۱ نشان دادند زمان لازم تقریباً به‌صورت خطی با زاویهٔ چرخش افزایش می‌یابد؛ به همین دلیل آن را نشانهٔ دگرگونی درونی واقعی می‌دانند نه حدس. این یکی از روشن‌ترین نشانگرهای توانایی فضایی است، عاملی جدا از استدلال کلامی و عددی.","چرا هر پاسخ نادرست تصویر آینه‌ای است","هر گزینهٔ نادرست، شکل مرجع بازتاب‌یافته است، نه شکلی دیگر. این مهم است: اگر گزینه‌های انحرافی صرفاً شکل‌های دیگر بودند، هر پرسش با شمردن مربع‌ها حل می‌شد و آزمون به‌جای چرخش، توجه را می‌سنجید. شکل بازتاب‌یافته هرگز با چرخاندن اصل در صفحه به دست نمی‌آید، پس تشخیص آن نیازمند چرخاندن واقعی در ذهن است. هر شکل پیش از استفاده از نظر نامتقارن بودن بررسی می‌شود، چون شکل متقارن با تصویر آینه‌ای خود یکسان است و پاسخ درست یکتایی نخواهد داشت.","آیا تمرین مؤثر است؟","بله، بیش از بیشتر تکالیف شناختی. مهارت فضایی به تمرین خوب پاسخ می‌دهد و پیشرفت به مسائل فضایی مرتبط منتقل می‌شود، اما نه به توانایی‌های بی‌ارتباط.","چرا ۲۰ شکل؟","به‌اندازه‌ای که چرخش‌های کوچک و بزرگ را پوشش دهد تا نمره کل دامنه را بازتاب دهد، و آزمون حدود شش دقیقه بماند. شکل‌ها هر بار از نو ساخته می‌شوند، پس کلید پاسخی برای حفظ کردن وجود ندارد."],
"fi": ["Mielikuvarotaatiotesti &#8212; ilmainen avaruudellisen päättelyn testi | CoreSkillAI","20 avaruudellista tehtävää: mikä kuvio on sama muoto käännettynä? Mittaa mielikuvarotaatiota, keskeistä avaruudellista kykyä. Ilmainen, ei rekisteröitymistä, uudet kuviot joka kerta.","Mielikuvarotaation tiede","Mielikuvarotaatio on kyky kuvitella esine kääntymässä ja arvioida, miltä se näyttäisi uudesta kulmasta. Shepard ja Metzler osoittivat vuonna 1971, että tarvittava aika kasvaa lähes lineaarisesti käännettävän kulman mukana, minkä vuoksi sitä pidetään todisteena aidosta sisäisestä muunnoksesta eikä arvauksesta. Se on yksi selkeimmistä avaruudellisen kyvyn merkeistä, tekijän joka erottuu sanallisesta ja numeerisesta päättelystä.","Miksi jokainen väärä vaihtoehto on peilikuva","Jokainen väärä vaihtoehto on kohdekuvio peilattuna, ei toinen muoto. Sillä on merkitystä: jos häirikkeet olisivat vain muita muotoja, jokaisen tehtävän voisi ratkaista ruutuja laskemalla ja testi mittaisi tarkkaavaisuutta eikä rotaatiota. Peilattua kuviota ei voi koskaan tuottaa kääntämällä alkuperäistä tasossa, joten erottaminen vaatii aitoa kääntämistä mielessä. Jokainen kuvio tarkistetaan epäsymmetriseksi ennen käyttöä, sillä symmetrinen muoto on identtinen oman peilikuvansa kanssa eikä sillä olisi yhtä oikeaa vastausta.","Auttaako harjoittelu?","Kyllä, enemmän kuin useimmissa kognitiivisissa tehtävissä. Avaruudellinen taito reagoi harjoitteluun hyvin ja hyöty siirtyy sukulaistehtäviin, muttei muihin kykyihin.","Miksi 20 kuviota?","Riittävästi kattamaan sekä pienet että suuret käännökset, jotta pistemäärä kuvaa koko vaihteluvälin, ja testi pysyy noin kuudessa minuutissa. Kuviot rakennetaan joka kerta uudelleen, joten ulkoa opeteltavaa vastausavainta ei ole."],
"fr": ["Test de rotation mentale &#8212; test gratuit de raisonnement spatial | CoreSkillAI","20 énigmes spatiales : quelle figure est la même forme, tournée ? Mesure la rotation mentale, une aptitude spatiale centrale. Gratuit, sans inscription, figures nouvelles à chaque essai.","La science de la rotation mentale","La rotation mentale est la capacité d'imaginer un objet en train de tourner et de juger de quoi il aurait l'air sous un autre angle. Shepard et Metzler ont montré en 1971 que le temps nécessaire croît presque linéairement avec l'angle à parcourir, ce qui en fait la preuve d'une transformation interne réelle plutôt que d'une supposition. C'est l'un des marqueurs les plus nets de l'aptitude spatiale, un facteur distinct du raisonnement verbal et numérique.","Pourquoi chaque mauvaise réponse est une image miroir","Chaque option incorrecte est la figure cible reflétée, non une forme différente. Cela compte : si les leurres étaient simplement d'autres formes, on résoudrait chaque item en comptant les carrés et la tâche mesurerait l'attention plutôt que la rotation. Une figure reflétée ne peut jamais être obtenue en tournant l'originale dans le plan ; les distinguer exige donc de la faire réellement tourner dans sa tête. Chaque figure est vérifiée asymétrique avant usage, car une forme symétrique est identique à son propre reflet et n'aurait pas de réponse unique.","L'entraînement aide-t-il ?","Oui, plus que pour la plupart des tâches cognitives. L'aptitude spatiale répond bien à l'entraînement et les gains se transfèrent à des problèmes spatiaux voisins, mais pas à des aptitudes sans rapport.","Pourquoi 20 figures ?","Assez pour couvrir petites et grandes rotations afin que le score reflète toute l'étendue, tout en tenant le test en six minutes environ. Les figures sont recréées à chaque essai : il n'y a donc aucun corrigé à mémoriser."],
"he": ["מבחן סיבוב מנטלי &#8212; מבחן חינמי לחשיבה מרחבית | CoreSkillAI","20 חידות מרחביות: איזו צורה היא אותה צורה, רק מסובבת? מודד סיבוב מנטלי, יכולת מרחבית מרכזית. חינם, בלי הרשמה, צורות חדשות בכל ניסיון.","המדע שמאחורי הסיבוב המנטלי","סיבוב מנטלי הוא היכולת לדמיין עצם מסתובב ולשפוט כיצד ייראה מזווית חדשה. שפרד ומצלר הראו ב-1971 שהזמן הנדרש עולה כמעט באופן ליניארי עם הזווית שיש לסובב, ולכן זה נחשב עדות לשינוי פנימי ממשי ולא לניחוש. זהו אחד הסמנים הברורים ביותר ליכולת מרחבית, גורם הנפרד מחשיבה מילולית ומספרית.","למה כל תשובה שגויה היא תמונת ראי","כל אפשרות שגויה היא צורת היעד המשוקפת, לא צורה אחרת. זה חשוב: אילו המסיחים היו פשוט צורות אחרות, אפשר היה לפתור כל פריט בספירת ריבועים והמטלה הייתה מודדת קשב במקום סיבוב. צורה משוקפת לעולם אינה נוצרת מסיבוב המקור במישור, ולכן ההבחנה מחייבת סיבוב אמיתי בראש. כל צורה נבדקת כאסימטרית לפני השימוש, מפני שצורה סימטרית זהה לתמונת הראי של עצמה ולא הייתה לה תשובה נכונה יחידה.","האם תרגול עוזר?","כן, יותר מברוב המטלות הקוגניטיביות. מיומנות מרחבית מגיבה היטב לאימון והרווחים עוברים לבעיות מרחביות קרובות, אך לא ליכולות שאינן קשורות.","למה 20 צורות?","מספיק כדי לכסות סיבובים קטנים וגדולים כך שהציון ישקף את מלוא הטווח, תוך שמירה על מבחן של כשש דקות. הצורות נבנות מחדש בכל ניסיון, ולכן אין מפתח תשובות לשנן."],
"hi": ["मानसिक घूर्णन परीक्षण &#8212; नि:शुल्क स्थानिक तर्क परीक्षण | CoreSkillAI","20 स्थानिक पहेलियाँ: कौन-सी आकृति वही है, बस घुमाई हुई? मानसिक घूर्णन मापता है, जो एक मूल स्थानिक क्षमता है। नि:शुल्क, बिना पंजीकरण, हर प्रयास में नई आकृतियाँ।","मानसिक घूर्णन के पीछे का विज्ञान","मानसिक घूर्णन किसी वस्तु को घूमते हुए कल्पित करने और यह आँकने की क्षमता है कि वह नए कोण से कैसी दिखेगी। शेपर्ड और मेट्ज़लर ने 1971 में दिखाया कि आवश्यक समय घुमाव के कोण के साथ लगभग रैखिक रूप से बढ़ता है, इसीलिए इसे वास्तविक आंतरिक रूपांतरण का प्रमाण माना जाता है, अनुमान का नहीं। यह स्थानिक क्षमता के सबसे स्पष्ट संकेतकों में से एक है, जो शाब्दिक और संख्यात्मक तर्क से अलग कारक है।","हर गलत उत्तर दर्पण-प्रतिबिंब क्यों है","हर गलत विकल्प लक्ष्य आकृति का परावर्तन है, कोई भिन्न आकृति नहीं। यह मायने रखता है: यदि भ्रामक विकल्प केवल अन्य आकृतियाँ होतीं, तो हर प्रश्न वर्ग गिनकर हल हो जाता और परीक्षण घूर्णन के बजाय ध्यान मापता। परावर्तित आकृति मूल को तल में घुमाकर कभी नहीं बनाई जा सकती, इसलिए भेद करने के लिए वास्तव में मन में घुमाना पड़ता है। उपयोग से पहले हर आकृति की असममितता जाँची जाती है, क्योंकि सममित आकृति अपने ही दर्पण-प्रतिबिंब के समान होती है और उसका एक ही सही उत्तर नहीं होता।","क्या अभ्यास से लाभ होता है?","हाँ, अधिकांश संज्ञानात्मक कार्यों से अधिक। स्थानिक कौशल प्रशिक्षण पर अच्छा प्रतिसाद देता है और लाभ संबंधित स्थानिक समस्याओं तक पहुँचता है, असंबद्ध क्षमताओं तक नहीं।","20 आकृतियाँ ही क्यों?","छोटे और बड़े दोनों घुमावों को समेटने के लिए पर्याप्त, ताकि अंक पूरी सीमा दर्शाए, और परीक्षण लगभग छह मिनट में सिमट जाए। हर प्रयास में आकृतियाँ नई बनती हैं, इसलिए याद करने को कोई उत्तर-कुंजी नहीं है।"],
"hr": ["Test mentalne rotacije &#8212; besplatan test prostornog zaključivanja | CoreSkillAI","20 prostornih zadataka: koji lik je isti oblik, samo zakrenut? Mjeri mentalnu rotaciju, temeljnu prostornu sposobnost. Besplatno, bez registracije, novi likovi pri svakom pokušaju.","Znanost iza mentalne rotacije","Mentalna rotacija je sposobnost da zamislite predmet kako se okreće i procijenite kako bi izgledao iz novog kuta. Shepard i Metzler pokazali su 1971. da vrijeme koje ljudima treba raste gotovo linearno s kutom zaokreta, zbog čega se to smatra dokazom stvarne unutarnje transformacije, a ne nagađanja. To je jedan od najjasnijih pokazatelja prostorne sposobnosti, faktora odvojenog od verbalnog i numeričkog zaključivanja.","Zašto je svaki netočan odgovor zrcalna slika","Svaka netočna opcija zrcalno je preslikan ciljni lik, a ne drugi oblik. To je važno: da su ometači jednostavno drugi oblici, svaki bi se zadatak riješio brojanjem kvadratića i test bi mjerio pažnju umjesto rotacije. Zrcaljeni lik nikada se ne može dobiti okretanjem izvornika u ravnini, pa razlikovanje zahtijeva stvarno okretanje u glavi. Svaki se lik prije uporabe provjerava da je asimetričan, jer je simetričan oblik istovjetan vlastitoj zrcalnoj slici i ne bi imao jedno točno rješenje.","Pomaže li vježba?","Da, više nego kod većine kognitivnih zadataka. Prostorna vještina dobro reagira na trening, a napredak se prenosi na srodne prostorne probleme, ali ne i na nepovezane sposobnosti.","Zašto 20 likova?","Dovoljno da pokriju i male i velike zaokrete kako bi rezultat odražavao cijeli raspon, a test ostaje na oko šest minuta. Likovi se izrađuju iznova pri svakom pokušaju, pa nema rješenja za pamćenje."],
"hu": ["Mentális forgatás teszt &#8212; ingyenes téri gondolkodás teszt | CoreSkillAI","20 téri feladat: melyik alakzat ugyanaz, csak elforgatva? A mentális forgatást méri, amely alapvető téri képesség. Ingyenes, regisztráció nélkül, minden alkalommal új alakzatok.","A mentális forgatás tudománya","A mentális forgatás az a képesség, hogy elképzeljünk egy forgó tárgyat, és megítéljük, hogyan nézne ki új szögből. Shepard és Metzler 1971-ben kimutatta, hogy a szükséges idő közel lineárisan nő az elforgatás szögével, ezért ezt valódi belső átalakítás bizonyítékának tekintik, nem találgatásnak. A téri képesség egyik legvilágosabb mutatója, olyan tényezőé, amely elkülönül a nyelvi és a számolási gondolkodástól.","Miért tükörkép minden rossz válasz","Minden helytelen lehetőség a célalakzat tükrözve, nem másik alak. Ez számít: ha a zavarók egyszerűen más alakzatok lennének, minden feladat megoldható volna négyzetszámolással, és a teszt figyelmet mérne forgatás helyett. Tükrözött alakzatot soha nem lehet az eredeti síkbeli elforgatásával előállítani, így a megkülönböztetéshez tényleges fejben forgatás kell. Minden alakzatot használat előtt ellenőrzünk, hogy aszimmetrikus-e, mert a szimmetrikus alak azonos a saját tükörképével, és nem lenne egyetlen helyes megoldása.","Segít a gyakorlás?","Igen, jobban, mint a legtöbb kognitív feladatnál. A téri készség jól reagál a gyakorlásra, és a nyereség átvihető rokon téri feladatokra, de nem független képességekre.","Miért 20 alakzat?","Elég a kis és nagy fordulatok lefedéséhez, hogy a pontszám a teljes tartományt tükrözze, miközben a teszt körülbelül hat perc marad. Az alakzatok minden alkalommal újonnan készülnek, így nincs megjegyezhető megoldókulcs."],
"id": ["Tes Rotasi Mental &#8212; tes penalaran spasial gratis | CoreSkillAI","20 teka-teki spasial: gambar mana yang merupakan bentuk sama, hanya diputar? Mengukur rotasi mental, kemampuan spasial inti. Gratis, tanpa daftar, gambar baru setiap percobaan.","Ilmu di Balik Rotasi Mental","Rotasi mental adalah kemampuan membayangkan sebuah benda berputar dan menilai bagaimana tampaknya dari sudut baru. Shepard dan Metzler menunjukkan pada 1971 bahwa waktu yang dibutuhkan naik hampir linear seiring besarnya sudut putaran, sehingga hal itu dianggap bukti transformasi batin yang nyata, bukan tebakan. Ini salah satu penanda paling jelas kemampuan spasial, faktor yang terpisah dari penalaran verbal dan numerik.","Mengapa setiap jawaban salah adalah bayangan cermin","Setiap pilihan salah adalah gambar acuan yang dicerminkan, bukan bentuk lain. Ini penting: bila pengecohnya sekadar bentuk berbeda, tiap soal bisa diselesaikan dengan menghitung kotak, dan tugasnya akan mengukur perhatian alih-alih rotasi. Gambar cermin tak pernah bisa dihasilkan dengan memutar aslinya di bidang datar, jadi membedakannya menuntut pemutaran nyata dalam pikiran. Setiap gambar diperiksa asimetris sebelum dipakai, sebab bentuk simetris identik dengan bayangan cerminnya sendiri dan tak akan punya satu jawaban benar.","Apakah latihan membantu?","Ya, lebih daripada kebanyakan tugas kognitif. Keterampilan spasial merespons latihan dengan baik dan hasilnya beralih ke masalah spasial terkait, tetapi tidak ke kemampuan yang tak berhubungan.","Mengapa 20 gambar?","Cukup untuk mencakup putaran kecil maupun besar agar skor mencerminkan rentang penuh, sambil menjaga tes sekitar enam menit. Gambar dibangun ulang setiap percobaan, jadi tak ada kunci jawaban untuk dihafal."],
"it": ["Test di rotazione mentale &#8212; test gratuito di ragionamento spaziale | CoreSkillAI","20 rompicapi spaziali: quale figura è la stessa forma, ruotata? Misura la rotazione mentale, un'abilità spaziale centrale. Gratis, senza registrazione, figure nuove a ogni tentativo.","La scienza della rotazione mentale","La rotazione mentale è la capacità di immaginare un oggetto che ruota e giudicare come apparirebbe da un'altra angolazione. Shepard e Metzler mostrarono nel 1971 che il tempo necessario cresce quasi linearmente con l'angolo da percorrere, motivo per cui è considerata prova di una vera trasformazione interna e non di un'ipotesi. È uno dei marcatori più chiari dell'abilità spaziale, un fattore distinto dal ragionamento verbale e numerico.","Perché ogni risposta sbagliata è un'immagine speculare","Ogni opzione errata è la figura bersaglio riflessa, non una forma diversa. Conta: se i distrattori fossero semplicemente altre forme, ogni item si risolverebbe contando i quadretti e il compito misurerebbe l'attenzione anziché la rotazione. Una figura riflessa non si ottiene mai ruotando l'originale nel piano, quindi distinguerle richiede di ruotarla davvero nella mente. Ogni figura è verificata asimmetrica prima dell'uso, perché una forma simmetrica coincide con la propria immagine speculare e non avrebbe un'unica risposta corretta.","L'allenamento serve?","Sì, più che nella maggior parte dei compiti cognitivi. L'abilità spaziale risponde bene all'allenamento e i guadagni si trasferiscono a problemi spaziali affini, ma non ad abilità estranee.","Perché 20 figure?","Abbastanza da coprire rotazioni piccole e ampie, così che il punteggio rifletta l'intero arco, mantenendo il test sui sei minuti. Le figure vengono ricreate a ogni tentativo, quindi non c'è alcuna soluzione da memorizzare."],
"ja": ["心的回転テスト &#8212; 無料の空間認識テスト | CoreSkillAI","20問の空間課題。どの図形が同じ形を回したものか。空間能力の中核である心的回転を測ります。無料、登録不要、毎回新しい図形。","心的回転を支える科学","心的回転とは、物が回る様子を思い浮かべ、別の角度からどう見えるかを判断する力です。シェパードとメツラーは1971年、必要な時間が回す角度にほぼ比例して増えることを示しました。だからこれは当て推量ではなく、頭の中で実際に変換が起きている証拠と考えられています。空間能力のもっとも明確な指標のひとつで、言語や数の推論とは別の因子です。","なぜ誤答がすべて鏡像なのか","誤りの選択肢はいずれも基準図形を反転させたもので、別の形ではありません。これは重要です。もし選択肢が単に別の形なら、マスの数を数えるだけで解けてしまい、回転ではなく注意力を測ることになります。反転した図形は、元の図形を平面内で回しても決して作れません。だから見分けるには頭の中で実際に回す必要があります。使用前にすべての図形が非対称かを確認します。対称な形は自分の鏡像と同一で、正解が一つに定まらないからです。","練習は効果がありますか","はい、多くの認知課題より効果があります。空間能力は訓練によく反応し、その効果は近い空間課題には及びますが、無関係な能力には及びません。","なぜ20問なのか","小さな回転と大きな回転の両方を含め、得点が全範囲を反映するのに十分な数でありながら、検査を約6分に収めるためです。図形は毎回作り直されるため、覚えるべき解答表はありません。"],
"ko": ["심적 회전 검사 &#8212; 무료 공간 추론 검사 | CoreSkillAI","20개의 공간 문제: 어느 도형이 같은 모양을 돌린 것일까요? 공간 능력의 핵심인 심적 회전을 측정합니다. 무료, 가입 불필요, 시도할 때마다 새로운 도형.","심적 회전의 과학적 배경","심적 회전은 물체가 도는 모습을 머릿속에 그리고 새로운 각도에서 어떻게 보일지 판단하는 능력입니다. 셰퍼드와 메츨러는 1971년, 필요한 시간이 돌려야 할 각도에 거의 비례해 늘어난다는 것을 보였습니다. 그래서 이것은 추측이 아니라 머릿속에서 실제 변환이 일어난다는 증거로 여겨집니다. 공간 능력의 가장 분명한 지표 가운데 하나이며, 언어나 수 추론과는 구별되는 요인입니다.","왜 오답이 모두 거울상인가","오답 선택지는 모두 기준 도형을 반사한 것이지 다른 모양이 아닙니다. 이것이 중요합니다. 오답이 그저 다른 모양이었다면 칸 수만 세어도 풀리기 때문에, 회전이 아니라 주의력을 재는 과제가 되어 버립니다. 반사된 도형은 원래 도형을 평면에서 아무리 돌려도 만들 수 없으므로, 구별하려면 머릿속에서 실제로 돌려 보아야 합니다. 사용 전 모든 도형이 비대칭인지 확인합니다. 대칭인 모양은 자기 거울상과 같아서 정답이 하나로 정해지지 않기 때문입니다.","연습이 도움이 되나요","네, 대부분의 인지 과제보다 도움이 됩니다. 공간 능력은 훈련에 잘 반응하며, 향상은 비슷한 공간 문제로 이어지지만 무관한 능력으로는 전이되지 않습니다.","왜 20문항인가","작은 회전과 큰 회전을 모두 포함해 점수가 전 범위를 반영하도록 하면서도 검사를 약 6분 안에 마치기 위해서입니다. 도형은 매번 새로 만들어지므로 외울 정답표가 없습니다."],
"lt": ["Mintinio sukimo testas &#8212; nemokamas erdvinio mąstymo testas | CoreSkillAI","20 erdvinių užduočių: kuri figūra yra ta pati forma, tik pasukta? Matuoja mintinį sukimą, esminį erdvinį gebėjimą. Nemokamai, be registracijos, kaskart naujos figūros.","Mokslas už mintinio sukimo","Mintinis sukimas – gebėjimas įsivaizduoti besisukantį objektą ir nuspręsti, kaip jis atrodytų iš naujo kampo. Shepardas ir Metzleris 1971 m. parodė, kad reikalingas laikas auga beveik tiesiškai su sukimo kampu; todėl tai laikoma tikros vidinės transformacijos, o ne spėjimo įrodymu. Tai vienas aiškiausių erdvinio gebėjimo rodiklių – veiksnio, atskiro nuo žodinio ir skaitinio mąstymo.","Kodėl kiekvienas neteisingas atsakymas yra veidrodinis","Kiekvienas neteisingas variantas yra atspindėta tikslinė figūra, o ne kita forma. Tai svarbu: jei blaškikliai būtų tiesiog kitos formos, kiekvieną užduotį išspręstumėte skaičiuodami langelius, ir testas matuotų dėmesį, o ne sukimą. Atspindėtos figūros niekada negausite sukdami originalą plokštumoje, tad atskirti reikia iš tiesų pasukus mintyse. Prieš naudojimą kiekviena figūra tikrinama, ar ji asimetriška, nes simetriška forma sutampa su savo veidrodiniu atvaizdu ir neturėtų vieno teisingo atsakymo.","Ar padeda treniruotės?","Taip, labiau nei daugumoje kognityvinių užduočių. Erdviniai gebėjimai gerai reaguoja į treniruotes, o pažanga persikelia į panašias erdvines užduotis, bet ne į nesusijusius gebėjimus.","Kodėl 20 figūrų?","Pakanka aprėpti ir mažus, ir didelius posūkius, kad rezultatas atspindėtų visą diapazoną, o testas telpa į maždaug šešias minutes. Figūros kuriamos iš naujo kiekvieną kartą, tad nėra ko įsiminti."],
"lv": ["Mentālās rotācijas tests &#8212; bezmaksas telpiskās domāšanas tests | CoreSkillAI","20 telpiski uzdevumi: kura figūra ir tā pati forma, tikai pagriezta? Mēra mentālo rotāciju, būtisku telpisko spēju. Bez maksas, bez reģistrācijas, katrā mēģinājumā jaunas figūras.","Zinātne aiz mentālās rotācijas","Mentālā rotācija ir spēja iztēloties griežamies priekšmetu un spriest, kā tas izskatītos no jauna leņķa. Šeperds un Meclers 1971. gadā parādīja, ka nepieciešamais laiks pieaug gandrīz lineāri ar pagrieziena leņķi, tāpēc to uzskata par pierādījumu īstai iekšējai pārveidei, nevis minējumam. Tas ir viens no skaidrākajiem telpiskās spējas rādītājiem — faktora, kas nošķirts no vārdiskās un skaitliskās domāšanas.","Kāpēc katra nepareizā atbilde ir spoguļattēls","Katrs nepareizais variants ir atspoguļota mērķa figūra, nevis cita forma. Tas ir svarīgi: ja traucēkļi būtu vienkārši citas formas, katru uzdevumu varētu atrisināt, saskaitot rūtiņas, un tests mērītu uzmanību, nevis rotāciju. Spoguļotu figūru nekad nevar iegūt, pagriežot oriģinālu plaknē, tāpēc atšķiršanai patiešām jāgriež prātā. Pirms lietošanas katra figūra tiek pārbaudīta, vai tā ir asimetriska, jo simetriska forma sakrīt ar savu spoguļattēlu un tai nebūtu vienas pareizas atbildes.","Vai treniņš palīdz?","Jā, vairāk nekā vairumā kognitīvo uzdevumu. Telpiskā prasme labi reaģē uz treniņu, un ieguvumi pārnesas uz radniecīgiem telpiskiem uzdevumiem, bet ne uz nesaistītām spējām.","Kāpēc 20 figūras?","Pietiekami, lai aptvertu gan mazus, gan lielus pagriezienus, tā ka rezultāts atspoguļo visu diapazonu, vienlaikus noturot testu ap sešām minūtēm. Figūras katrā mēģinājumā tiek veidotas no jauna, tāpēc nav ko iegaumēt."],
"mk": ["Тест за ментална ротација &#8212; бесплатен тест за просторно расудување | CoreSkillAI","20 просторни задачи: која фигура е истата форма, само завртена? Мери ментална ротација, основна просторна способност. Бесплатно, без регистрација, нови фигури при секој обид.","Науката зад менталната ротација","Менталната ротација е способноста да замислите предмет како се врти и да процените како би изгледал од нов агол. Шепард и Мецлер во 1971 година покажаа дека потребното време расте речиси линеарно со аголот на вртење, па затоа тоа се смета за доказ за вистинска внатрешна трансформација, а не за погодување. Тоа е еден од најјасните показатели на просторната способност, фактор одвоен од вербалното и нумеричкото расудување.","Зошто секој погрешен одговор е огледална слика","Секоја погрешна опција е целната фигура отсликана, а не друга форма. Тоа е важно: ако одвлекувачите беа само други форми, секоја задача би се решавала со броење квадратчиња и тестот би мерел внимание наместо ротација. Отсликана фигура никогаш не може да се добие со вртење на оригиналот во рамнина, па разликувањето бара вистинско вртење во главата. Пред употреба секоја фигура се проверува дали е асиметрична, зашто симетричната форма е идентична со сопствената огледална слика и не би имала еден точен одговор.","Дали помага вежбањето?","Да, повеќе отколку кај повеќето когнитивни задачи. Просторната вештина добро реагира на тренинг, а придобивките се пренесуваат на сродни просторни проблеми, но не и на неповрзани способности.","Зошто 20 фигури?","Доволно за да ги опфатат и малите и големите вртења, така што резултатот го одразува целиот распон, а тестот останува околу шест минути. Фигурите се создаваат одново при секој обид, па нема клуч со одговори за помнење."],
"ms": ["Ujian Putaran Mental &#8212; ujian penaakulan ruang percuma | CoreSkillAI","20 teka-teki ruang: rajah mana yang bentuknya sama, cuma diputar? Mengukur putaran mental, keupayaan ruang teras. Percuma, tanpa pendaftaran, rajah baharu setiap percubaan.","Sains di Sebalik Putaran Mental","Putaran mental ialah keupayaan membayangkan objek berputar dan menilai rupanya dari sudut baharu. Shepard dan Metzler menunjukkan pada 1971 bahawa masa yang diperlukan meningkat hampir secara linear dengan sudut putaran, justeru ia dianggap bukti transformasi dalaman sebenar dan bukan tekaan. Ia salah satu penanda paling jelas keupayaan ruang, faktor yang terpisah daripada penaakulan lisan dan berangka.","Mengapa setiap jawapan salah ialah imej cermin","Setiap pilihan salah ialah rajah sasaran yang dipantulkan, bukan bentuk lain. Ini penting: jika pengganggu sekadar bentuk lain, setiap item boleh diselesaikan dengan mengira petak dan tugas itu akan mengukur perhatian, bukan putaran. Rajah terpantul tidak pernah boleh dihasilkan dengan memutar yang asal pada satah, jadi membezakannya menuntut putaran sebenar dalam fikiran. Setiap rajah disemak supaya tidak simetri sebelum digunakan, kerana bentuk simetri serupa dengan imej cerminnya sendiri dan tidak akan mempunyai satu jawapan betul.","Adakah latihan membantu?","Ya, lebih daripada kebanyakan tugas kognitif. Kemahiran ruang bertindak balas dengan baik terhadap latihan dan peningkatannya berpindah kepada masalah ruang berkaitan, tetapi bukan kepada keupayaan yang tidak berkaitan.","Mengapa 20 rajah?","Cukup untuk merangkumi putaran kecil dan besar supaya skor mencerminkan julat penuh, sambil mengekalkan ujian sekitar enam minit. Rajah dibina semula setiap percubaan, jadi tiada kunci jawapan untuk dihafal."],
"nl": ["Mentale rotatietest &#8212; gratis test ruimtelijk redeneren | CoreSkillAI","20 ruimtelijke puzzels: welke figuur is dezelfde vorm, gedraaid? Meet mentale rotatie, een kernvaardigheid in ruimtelijk inzicht. Gratis, geen registratie, nieuwe figuren elke poging.","De wetenschap achter mentale rotatie","Mentale rotatie is het vermogen je een voorwerp voor te stellen dat draait en te beoordelen hoe het er vanuit een nieuwe hoek uit zou zien. Shepard en Metzler lieten in 1971 zien dat de benodigde tijd bijna lineair stijgt met de hoek waarover je moet draaien; daarom geldt het als bewijs van een echte inwendige transformatie in plaats van een gok. Het is een van de duidelijkste markers van ruimtelijk vermogen, een factor die losstaat van verbaal en numeriek redeneren.","Waarom elk fout antwoord een spiegelbeeld is","Elke onjuiste optie is de doelfiguur gespiegeld, niet een andere vorm. Dat is belangrijk: waren de afleiders simpelweg andere vormen, dan zou je elk item kunnen oplossen door vakjes te tellen en zou de taak aandacht meten in plaats van rotatie. Een gespiegelde figuur kan nooit ontstaan door het origineel in het vlak te draaien, dus onderscheiden vereist werkelijk draaien in je hoofd. Elke figuur wordt vóór gebruik op asymmetrie gecontroleerd, want een symmetrische vorm is gelijk aan zijn eigen spiegelbeeld en zou geen enkel juist antwoord hebben.","Helpt oefenen?","Ja, meer dan bij de meeste cognitieve taken. Ruimtelijke vaardigheid reageert goed op training en de winst draagt over naar verwante ruimtelijke problemen, maar niet naar ongerelateerde vermogens.","Waarom 20 figuren?","Genoeg om kleine én grote draaiingen te dekken zodat de score het hele bereik weerspiegelt, terwijl de test rond de zes minuten blijft. De figuren worden elke poging opnieuw gemaakt, dus er valt geen antwoordsleutel te onthouden."],
"no": ["Mental rotasjonstest &#8212; gratis test i romlig tenkning | CoreSkillAI","20 romlige oppgaver: hvilken figur er samme form, bare dreid? Måler mental rotasjon, en sentral romlig evne. Gratis, uten registrering, nye figurer hver gang.","Vitenskapen bak mental rotasjon","Mental rotasjon er evnen til å forestille seg en gjenstand som dreier, og vurdere hvordan den ville sett ut fra en ny vinkel. Shepard og Metzler viste i 1971 at tiden folk trenger, stiger nesten lineært med vinkelen de må dreie gjennom, og derfor regnes det som tegn på en reell indre omforming heller enn gjetning. Det er en av de tydeligste markørene på romlig evne, en faktor som står atskilt fra språklig og numerisk resonnering.","Derfor er hvert galt svar et speilbilde","Hvert galt alternativ er målfiguren speilvendt, ikke en annen form. Det betyr noe: hvis distraktorene bare var andre former, kunne hver oppgave løses ved å telle ruter, og oppgaven ville måle oppmerksomhet i stedet for rotasjon. En speilvendt figur kan aldri lages ved å dreie originalen i planet, så å skille dem krever ekte dreining i hodet. Hver figur kontrolleres for asymmetri før bruk, fordi en symmetrisk form er identisk med sitt eget speilbilde og ikke ville hatt ett riktig svar.","Hjelper trening?","Ja, mer enn i de fleste kognitive oppgaver. Romlige ferdigheter responderer godt på trening, og gevinsten overføres til beslektede romlige problemer, men ikke til urelaterte evner.","Hvorfor 20 figurer?","Nok til å dekke både små og store dreininger slik at skåren gjenspeiler hele spennet, samtidig som testen holdes på rundt seks minutter. Figurene lages nye hver gang, så det finnes ingen fasit å pugge."],
"pl": ["Test rotacji mentalnej &#8212; darmowy test myślenia przestrzennego | CoreSkillAI","20 zadań przestrzennych: która figura to ten sam kształt, tylko obrócony? Mierzy rotację mentalną, podstawową zdolność przestrzenną. Za darmo, bez rejestracji, nowe figury przy każdym podejściu.","Nauka stojąca za rotacją mentalną","Rotacja mentalna to zdolność wyobrażenia sobie obracającego się przedmiotu i oceny, jak wyglądałby pod nowym kątem. Shepard i Metzler wykazali w 1971 roku, że potrzebny czas rośnie niemal liniowo wraz z kątem obrotu, dlatego uznaje się to za dowód rzeczywistego wewnętrznego przekształcenia, a nie zgadywania. To jeden z najwyraźniejszych wskaźników zdolności przestrzennych, czynnika odrębnego od rozumowania werbalnego i liczbowego.","Dlaczego każda błędna odpowiedź jest odbiciem lustrzanym","Każda niepoprawna opcja to odbita figura wzorcowa, a nie inny kształt. To ma znaczenie: gdyby dystraktory były po prostu innymi kształtami, każde zadanie dałoby się rozwiązać, licząc kratki, a test mierzyłby uwagę zamiast rotacji. Odbitej figury nigdy nie da się uzyskać przez obrót oryginału w płaszczyźnie, więc rozróżnienie wymaga faktycznego obracania w głowie. Każdą figurę sprawdza się przed użyciem pod kątem asymetrii, bo kształt symetryczny jest tożsamy z własnym odbiciem i nie miałby jednej poprawnej odpowiedzi.","Czy ćwiczenie pomaga?","Tak, bardziej niż w większości zadań poznawczych. Zdolność przestrzenna dobrze reaguje na trening, a zyski przenoszą się na pokrewne problemy przestrzenne, lecz nie na niepowiązane zdolności.","Dlaczego 20 figur?","Wystarczająco, by objąć małe i duże obroty, tak aby wynik odzwierciedlał pełen zakres, a test mieścił się w około sześciu minutach. Figury powstają na nowo przy każdym podejściu, więc nie ma czego zapamiętywać."],
"pt": ["Teste de rotação mental &#8212; teste gratuito de raciocínio espacial | CoreSkillAI","20 puzzles espaciais: que figura é a mesma forma, rodada? Mede a rotação mental, uma capacidade espacial central. Grátis, sem registo, figuras novas em cada tentativa.","A ciência da rotação mental","A rotação mental é a capacidade de imaginar um objeto a girar e julgar como ficaria visto de outro ângulo. Shepard e Metzler mostraram em 1971 que o tempo necessário cresce quase linearmente com o ângulo a percorrer, pelo que é encarado como prova de uma transformação interna real e não de um palpite. É um dos marcadores mais claros da capacidade espacial, um fator distinto do raciocínio verbal e numérico.","Porque cada resposta errada é uma imagem espelhada","Cada opção incorreta é a figura alvo refletida, não uma forma diferente. Isso importa: se os distratores fossem simplesmente outras formas, cada item resolver-se-ia a contar quadrados e a tarefa mediria atenção em vez de rotação. Uma figura refletida nunca se obtém rodando a original no plano, pelo que distingui-las exige rodá-la de facto na cabeça. Cada figura é verificada como assimétrica antes de ser usada, porque uma forma simétrica é idêntica ao seu próprio reflexo e não teria uma única resposta certa.","Praticar ajuda?","Sim, mais do que na maioria das tarefas cognitivas. A competência espacial responde bem ao treino e os ganhos transferem-se para problemas espaciais próximos, mas não para capacidades não relacionadas.","Porquê 20 figuras?","Suficientes para cobrir rotações pequenas e grandes, de modo que a pontuação reflita todo o intervalo, mantendo o teste em cerca de seis minutos. As figuras são criadas de novo em cada tentativa, pelo que não há chave de respostas para decorar."],
"ro": ["Test de rotație mentală &#8212; test gratuit de raționament spațial | CoreSkillAI","20 de puzzle-uri spațiale: care figură este aceeași formă, rotită? Măsoară rotația mentală, o abilitate spațială esențială. Gratuit, fără cont, figuri noi la fiecare încercare.","Știința din spatele rotației mentale","Rotația mentală este capacitatea de a-ți imagina un obiect rotindu-se și de a judeca cum ar arăta dintr-un unghi nou. Shepard și Metzler au arătat în 1971 că timpul necesar crește aproape liniar cu unghiul de rotit, motiv pentru care este considerat dovada unei transformări interioare reale, nu a unei ghiciri. Este unul dintre cei mai clari indicatori ai abilității spațiale, un factor distinct de raționamentul verbal și numeric.","De ce fiecare răspuns greșit este o imagine în oglindă","Fiecare variantă incorectă este figura țintă reflectată, nu o altă formă. Contează: dacă distractorii ar fi pur și simplu alte forme, fiecare item s-ar rezolva numărând pătrățele, iar sarcina ar măsura atenția în loc de rotație. O figură reflectată nu poate fi obținută niciodată rotind originalul în plan, așa că deosebirea cere rotire reală în minte. Fiecare figură este verificată să fie asimetrică înainte de folosire, fiindcă o formă simetrică este identică propriei imagini în oglindă și nu ar avea un singur răspuns corect.","Ajută exercițiul?","Da, mai mult decât la majoritatea sarcinilor cognitive. Abilitatea spațială răspunde bine la antrenament, iar câștigurile se transferă la probleme spațiale înrudite, dar nu la abilități fără legătură.","De ce 20 de figuri?","Suficiente pentru a acoperi rotații mici și mari, astfel încât scorul să reflecte întregul interval, păstrând testul la aproximativ șase minute. Figurile sunt create din nou la fiecare încercare, deci nu există grilă de memorat."],
"ru": ["Тест мысленного вращения &#8212; бесплатный тест пространственного мышления | CoreSkillAI","20 пространственных задач: какая фигура — та же форма, только повёрнутая? Измеряет мысленное вращение, ключевую пространственную способность. Бесплатно, без регистрации, каждый раз новые фигуры.","Наука о мысленном вращении","Мысленное вращение — способность представить поворачивающийся предмет и оценить, как он выглядел бы под новым углом. Шепард и Метцлер в 1971 году показали, что необходимое время растёт почти линейно с углом поворота, поэтому это считают свидетельством настоящего внутреннего преобразования, а не догадки. Это один из самых чётких показателей пространственной способности — фактора, отдельного от словесного и числового мышления.","Почему каждый неверный ответ — зеркальный","Каждый неверный вариант — это отражённая целевая фигура, а не другая форма. Это важно: будь отвлекающие варианты просто другими фигурами, любое задание решалось бы подсчётом клеток, и тест измерял бы внимание, а не вращение. Отражённую фигуру невозможно получить поворотом оригинала в плоскости, поэтому различить их можно, только действительно повернув её в уме. Каждая фигура перед использованием проверяется на асимметрию, потому что симметричная форма совпадает со своим зеркальным отражением и не имела бы единственного верного ответа.","Помогают ли тренировки?","Да, больше, чем в большинстве когнитивных задач. Пространственный навык хорошо поддаётся тренировке, и прирост переносится на близкие пространственные задачи, но не на несвязанные способности.","Почему 20 фигур?","Достаточно, чтобы охватить и малые, и большие повороты, чтобы балл отражал весь диапазон, и при этом тест укладывается примерно в шесть минут. Фигуры создаются заново при каждой попытке, поэтому запоминать нечего."],
"sk": ["Test mentálnej rotácie &#8212; bezplatný test priestorového uvažovania | CoreSkillAI","20 priestorových úloh: ktorý útvar je ten istý tvar, len otočený? Meria mentálnu rotáciu, základnú priestorovú schopnosť. Zadarmo, bez registrácie, nové útvary pri každom pokuse.","Veda za mentálnou rotáciou","Mentálna rotácia je schopnosť predstaviť si otáčajúci sa predmet a posúdiť, ako by vyzeral z nového uhla. Shepard a Metzler v roku 1971 ukázali, že potrebný čas rastie takmer lineárne s uhlom otočenia, preto sa to považuje za dôkaz skutočnej vnútornej premeny, nie odhadu. Je to jeden z najjasnejších ukazovateľov priestorovej schopnosti, faktora odlišného od slovného a číselného uvažovania.","Prečo je každá zlá odpoveď zrkadlovým obrazom","Každá nesprávna možnosť je cieľový útvar zrkadlovo prevrátený, nie iný tvar. Záleží na tom: keby boli rozptyľovače jednoducho iné tvary, každú úlohu by sa dalo vyriešiť počítaním štvorčekov a test by meral pozornosť namiesto rotácie. Zrkadlený útvar nemožno získať otáčaním originálu v rovine, takže rozlíšenie vyžaduje skutočné otáčanie v hlave. Každý útvar sa pred použitím kontroluje na asymetriu, lebo symetrický tvar je totožný so svojím zrkadlovým obrazom a nemal by jediné správne riešenie.","Pomáha tréning?","Áno, viac než pri väčšine kognitívnych úloh. Priestorová zručnosť dobre reaguje na tréning a zisky sa prenášajú na príbuzné priestorové problémy, nie však na nesúvisiace schopnosti.","Prečo 20 útvarov?","Dosť na pokrytie malých aj veľkých otočení, aby skóre odrážalo celý rozsah, a test pritom zostáva okolo šiestich minút. Útvary vznikajú pri každom pokuse nanovo, takže niet čo memorovať."],
"sl": ["Test miselne rotacije &#8212; brezplačen test prostorskega sklepanja | CoreSkillAI","20 prostorskih nalog: kateri lik je ista oblika, le zavrten? Meri miselno rotacijo, temeljno prostorsko sposobnost. Brezplačno, brez registracije, novi liki ob vsakem poskusu.","Znanost za miselno rotacijo","Miselna rotacija je sposobnost, da si predstavljate predmet, kako se vrti, in presodite, kako bi bil videti iz novega kota. Shepard in Metzler sta leta 1971 pokazala, da potreben čas raste skoraj linearno s kotom zasuka, zato to velja za dokaz resnične notranje preobrazbe in ne ugibanja. Je eden najjasnejših kazalnikov prostorske sposobnosti, dejavnika, ločenega od besednega in številskega sklepanja.","Zakaj je vsak napačen odgovor zrcalna slika","Vsaka napačna možnost je zrcaljen ciljni lik, ne druga oblika. To je pomembno: če bi bili motilci preprosto druge oblike, bi vsako nalogo rešili s štetjem kvadratkov in test bi meril pozornost namesto rotacije. Zrcaljenega lika ni mogoče dobiti z vrtenjem izvirnika v ravnini, zato razlikovanje zahteva resnično vrtenje v glavi. Vsak lik pred uporabo preverimo, ali je asimetričen, saj je simetrična oblika enaka svoji zrcalni sliki in ne bi imela enega pravilnega odgovora.","Ali vaja pomaga?","Da, bolj kot pri večini kognitivnih nalog. Prostorska spretnost se dobro odziva na vadbo, pridobitve pa se prenesejo na sorodne prostorske probleme, ne pa na nepovezane sposobnosti.","Zakaj 20 likov?","Dovolj, da pokrijejo majhne in velike zasuke, tako da rezultat odraža celoten razpon, test pa ostane pri približno šestih minutah. Liki se ob vsakem poskusu ustvarijo na novo, zato ni ničesar za učenje na pamet."],
"sq": ["Testi i rrotullimit mendor &#8212; test falas i arsyetimit hapësinor | CoreSkillAI","20 enigma hapësinore: cila figurë është e njëjta formë, e rrotulluar? Mat rrotullimin mendor, një aftësi hapësinore themelore. Falas, pa regjistrim, figura të reja çdo herë.","Shkenca pas rrotullimit mendor","Rrotullimi mendor është aftësia për të imagjinuar një objekt duke u rrotulluar dhe për të gjykuar si do të dukej nga një kënd i ri. Shepard dhe Metzler treguan në 1971 se koha e nevojshme rritet pothuajse në mënyrë lineare me këndin e rrotullimit, prandaj kjo merret si dëshmi e një transformimi të vërtetë të brendshëm dhe jo e hamendjes. Është një nga treguesit më të qartë të aftësisë hapësinore, një faktor i ndarë nga arsyetimi verbal dhe numerik.","Pse çdo përgjigje e gabuar është pasqyrim","Çdo mundësi e pasaktë është figura e synuar e pasqyruar, jo një formë tjetër. Kjo ka rëndësi: nëse shpërqendruesit do të ishin thjesht forma të tjera, çdo pyetje do të zgjidhej duke numëruar katrorët dhe detyra do të maste vëmendjen në vend të rrotullimit. Një figurë e pasqyruar nuk mund të prodhohet kurrë duke rrotulluar origjinalin në plan, prandaj dallimi kërkon rrotullim të vërtetë në mendje. Çdo figurë kontrollohet të jetë asimetrike para përdorimit, sepse një formë simetrike është e njëjtë me pasqyrimin e vet dhe nuk do të kishte një përgjigje të vetme të saktë.","A ndihmon stërvitja?","Po, më shumë se në shumicën e detyrave njohëse. Aftësia hapësinore i përgjigjet mirë stërvitjes dhe përfitimet kalojnë te problemet hapësinore të ngjashme, por jo te aftësi të palidhura.","Pse 20 figura?","Mjaftueshëm për të mbuluar rrotullime të vogla dhe të mëdha, që rezultati të pasqyrojë gjithë gamën, ndërsa testi mbetet rreth gjashtë minuta. Figurat ndërtohen nga e para çdo herë, prandaj nuk ka çelës përgjigjesh për të mësuar përmendsh."],
"sr": ["Тест менталне ротације &#8212; бесплатан тест просторног закључивања | CoreSkillAI","20 просторних задатака: који лик је исти облик, само заокренут? Мери менталну ротацију, основну просторну способност. Бесплатно, без регистрације, нови ликови при сваком покушају.","Наука иза менталне ротације","Ментална ротација је способност да замислите предмет како се окреће и процените како би изгледао из новог угла. Шепард и Мецлер су 1971. показали да потребно време расте готово линеарно са углом заокрета, због чега се то сматра доказом стварне унутрашње трансформације, а не нагађања. То је један од најјаснијих показатеља просторне способности, фактора одвојеног од вербалног и нумеричког закључивања.","Зашто је сваки нетачан одговор огледална слика","Свака нетачна опција је циљни лик пресликан у огледалу, а не други облик. То је важно: да су ометачи једноставно други облици, сваки задатак би се решавао бројањем квадратића и тест би мерио пажњу уместо ротације. Пресликани лик се никада не може добити окретањем оригинала у равни, па разликовање захтева стварно окретање у глави. Сваки лик се пре употребе проверава да ли је асиметричан, јер је симетричан облик истоветан сопственој огледалној слици и не би имао једно тачно решење.","Да ли вежба помаже?","Да, више него код већине когнитивних задатака. Просторна вештина добро реагује на тренинг, а напредак се преноси на сродне просторне проблеме, али не и на неповезане способности.","Зашто 20 ликова?","Довољно да покрију и мале и велике заокрете како би резултат одражавао цео распон, а тест остаје на око шест минута. Ликови се израђују изнова при сваком покушају, па нема решења за памћење."],
"sv": ["Test i mental rotation &#8212; gratis test i rumsligt tänkande | CoreSkillAI","20 rumsliga uppgifter: vilken figur är samma form, fast vriden? Mäter mental rotation, en central rumslig förmåga. Gratis, ingen registrering, nya figurer varje gång.","Vetenskapen bakom mental rotation","Mental rotation är förmågan att föreställa sig ett föremål som vrids och bedöma hur det skulle se ut från en ny vinkel. Shepard och Metzler visade 1971 att den tid människor behöver stiger nästan linjärt med vinkeln de måste vrida genom, och därför ses det som bevis för en verklig inre omvandling snarare än en gissning. Det är en av de tydligaste markörerna för rumslig förmåga, en faktor skild från språkligt och numeriskt resonemang.","Därför är varje fel svar en spegelbild","Varje felaktigt alternativ är målfiguren speglad, inte en annan form. Det spelar roll: om distraktorerna bara vore andra former skulle varje uppgift kunna lösas genom att räkna rutor, och uppgiften skulle mäta uppmärksamhet i stället för rotation. En speglad figur kan aldrig skapas genom att vrida originalet i planet, så att skilja dem åt kräver verklig vridning i huvudet. Varje figur kontrolleras som asymmetrisk före användning, eftersom en symmetrisk form är identisk med sin egen spegelbild och inte skulle ha ett enda rätt svar.","Hjälper träning?","Ja, mer än vid de flesta kognitiva uppgifter. Rumslig färdighet svarar väl på träning och vinsterna förs över till närbesläktade rumsliga problem, men inte till orelaterade förmågor.","Varför 20 figurer?","Tillräckligt för att täcka både små och stora vridningar så att poängen speglar hela spannet, samtidigt som testet håller sig kring sex minuter. Figurerna skapas nya varje gång, så det finns inget facit att lära sig utantill."],
"sw": ["Kipimo cha Mzunguko wa Kiakili &#8212; kipimo bure cha ufikiri wa nafasi | CoreSkillAI","Mafumbo 20 ya nafasi: ni umbo lipi lilelile, likiwa limezungushwa? Hupima mzunguko wa kiakili, uwezo msingi wa nafasi. Bure, bila kujisajili, maumbo mapya kila jaribio.","Sayansi Nyuma ya Mzunguko wa Kiakili","Mzunguko wa kiakili ni uwezo wa kuwazia kitu kikizunguka na kuhukumu jinsi kingeonekana kutoka pembe mpya. Shepard na Metzler walionyesha mwaka 1971 kwamba muda unaohitajika hupanda karibu kwa mstari sawia na pembe ya kuzungusha, ndiyo maana hii huchukuliwa kuwa ushahidi wa mabadiliko halisi ya ndani badala ya kubahatisha. Ni mojawapo ya viashiria vilivyo wazi zaidi vya uwezo wa nafasi, kipengele kilicho tofauti na ufikiri wa maneno na wa namba.","Kwa nini kila jibu lisilo sahihi ni taswira ya kioo","Kila chaguo lisilo sahihi ni umbo lengwa lililoakisiwa, si umbo tofauti. Hili ni muhimu: kama vipotoshi vingekuwa maumbo mengine tu, kila swali lingetatuliwa kwa kuhesabu miraba, na kazi ingepima umakini badala ya mzunguko. Umbo lililoakisiwa haliwezi kamwe kupatikana kwa kuzungusha la asili katika uso tambarare, hivyo kutofautisha kunahitaji kuzungusha kwelikweli akilini. Kila umbo hukaguliwa kuwa lisilo sawia kabla ya kutumika, kwa sababu umbo sawia linafanana na taswira yake ya kioo na halingekuwa na jibu moja sahihi.","Je, mazoezi husaidia?","Ndiyo, zaidi kuliko kazi nyingi za kiakili. Ustadi wa nafasi hujibu vizuri mafunzo na faida huhamia matatizo ya nafasi yanayohusiana, lakini si uwezo usiohusiana.","Kwa nini maumbo 20?","Yanatosha kufunika mizunguko midogo na mikubwa ili alama iakisi upeo wote, huku kipimo kikibaki karibu dakika sita. Maumbo hujengwa upya kila jaribio, hivyo hakuna jibu la kukariri."],
"th": ["แบบทดสอบการหมุนภาพในใจ &#8212; แบบทดสอบการให้เหตุผลเชิงพื้นที่ฟรี | CoreSkillAI","โจทย์เชิงพื้นที่ 20 ข้อ รูปใดคือรูปเดิมที่ถูกหมุน วัดการหมุนภาพในใจซึ่งเป็นความสามารถเชิงพื้นที่หลัก ฟรี ไม่ต้องสมัคร และได้รูปใหม่ทุกครั้ง","วิทยาศาสตร์เบื้องหลังการหมุนภาพในใจ","การหมุนภาพในใจคือความสามารถในการนึกภาพวัตถุกำลังหมุนและตัดสินว่ามันจะดูเป็นอย่างไรจากมุมใหม่ เชพเพิร์ดและเมตซ์เลอร์แสดงไว้ในปี 1971 ว่าเวลาที่ต้องใช้เพิ่มขึ้นเกือบเป็นเส้นตรงตามมุมที่ต้องหมุน จึงถือเป็นหลักฐานของการแปลงภาพภายในจริง ไม่ใช่การเดา นี่เป็นหนึ่งในตัวชี้วัดความสามารถเชิงพื้นที่ที่ชัดเจนที่สุด ซึ่งเป็นองค์ประกอบที่แยกจากการให้เหตุผลด้านภาษาและตัวเลข","ทำไมตัวเลือกที่ผิดจึงเป็นภาพสะท้อนกระจกทั้งหมด","ตัวเลือกที่ผิดทุกตัวคือรูปต้นแบบที่ถูกสะท้อน ไม่ใช่รูปอื่น เรื่องนี้สำคัญ เพราะถ้าตัวลวงเป็นเพียงรูปอื่น ก็จะแก้ทุกข้อได้ด้วยการนับช่อง และแบบทดสอบจะวัดความใส่ใจแทนการหมุน รูปที่สะท้อนแล้วไม่มีทางเกิดจากการหมุนรูปเดิมบนระนาบ การแยกแยะจึงต้องหมุนในใจจริง ๆ ทุกรูปจะถูกตรวจว่าไม่สมมาตรก่อนนำมาใช้ เพราะรูปสมมาตรจะเหมือนกับภาพสะท้อนของตัวเองและจะไม่มีคำตอบที่ถูกเพียงข้อเดียว","การฝึกช่วยได้ไหม","ได้ และช่วยมากกว่างานทางปัญญาส่วนใหญ่ ทักษะเชิงพื้นที่ตอบสนองต่อการฝึกได้ดี และผลที่ได้ถ่ายโอนไปยังโจทย์เชิงพื้นที่ที่เกี่ยวข้อง แต่ไม่ถ่ายโอนไปยังความสามารถที่ไม่เกี่ยวข้อง","ทำไมต้อง 20 รูป","มากพอที่จะครอบคลุมทั้งการหมุนน้อยและหมุนมาก เพื่อให้คะแนนสะท้อนทั้งช่วง ขณะที่คุมเวลาไว้ราวหกนาที รูปถูกสร้างใหม่ทุกครั้งที่ทำ จึงไม่มีเฉลยให้ท่องจำ"],
"tl": ["Pagsusulit sa Mental Rotation &#8212; libreng pagsusulit sa pangangatwirang pang-espasyo | CoreSkillAI","20 palaisipang pang-espasyo: aling hugis ang siya ring hugis, ipinihit lang? Sinusukat ang mental rotation, isang pangunahing kakayahang pang-espasyo. Libre, walang rehistro, bagong hugis bawat pagsubok.","Ang Agham sa Likod ng Mental Rotation","Ang mental rotation ay ang kakayahang isipin ang isang bagay na umiikot at hulaan kung ano ang itsura nito mula sa bagong anggulo. Ipinakita nina Shepard at Metzler noong 1971 na ang oras na kailangan ay tumataas nang halos linear kasabay ng anggulong kailangang ikutin, kaya ito itinuturing na patunay ng tunay na panloob na pagbabago at hindi hula. Isa ito sa pinakamalinaw na palatandaan ng kakayahang pang-espasyo, isang salik na hiwalay sa pangangatwirang berbal at numerikal.","Bakit salamin ang bawat maling sagot","Bawat maling pagpipilian ay ang target na hugis na sinalamin, hindi ibang hugis. Mahalaga ito: kung ibang hugis lang ang mga pang-lito, malulutas mo ang bawat aytem sa pagbibilang ng parisukat, at susukatin ng gawain ang atensyon sa halip na pag-ikot. Hindi kailanman malilikha ang sinalaming hugis sa pamamagitan ng pag-ikot ng orihinal sa patag, kaya ang pagkakaiba ay nangangailangan ng tunay na pag-ikot sa isip. Sinusuri ang bawat hugis na asimetriko bago gamitin, dahil ang simetrikong hugis ay kapareho ng sarili nitong salamin at walang iisang tamang sagot.","Nakakatulong ba ang pagsasanay?","Oo, higit pa kaysa sa karamihan ng gawaing pangkaisipan. Mahusay tumutugon ang kasanayang pang-espasyo sa pagsasanay at nalilipat ang pag-unlad sa kaugnay na mga suliraning pang-espasyo, ngunit hindi sa mga di-kaugnay na kakayahan.","Bakit 20 hugis?","Sapat para masaklaw ang maliliit at malalaking ikot upang mailarawan ng iskor ang buong saklaw, habang nananatiling mga anim na minuto ang pagsusulit. Bagong likha ang mga hugis sa bawat pagsubok, kaya walang susi sa sagot na kabisaduhin."],
"tr": ["Zihinsel Döndürme Testi &#8212; ücretsiz uzamsal muhakeme testi | CoreSkillAI","20 uzamsal bulmaca: hangi şekil aynı şeklin döndürülmüş hâli? Uzamsal yeteneğin çekirdeği olan zihinsel döndürmeyi ölçer. Ücretsiz, kayıtsız, her denemede yeni şekiller.","Zihinsel Döndürmenin Arkasındaki Bilim","Zihinsel döndürme, bir nesnenin döndüğünü gözünüzde canlandırıp yeni bir açıdan nasıl görüneceğini kestirebilme yeteneğidir. Shepard ve Metzler 1971'de, gereken sürenin döndürülmesi gereken açıyla neredeyse doğrusal biçimde arttığını gösterdi; bu yüzden bu, tahmin değil gerçek bir içsel dönüşümün kanıtı sayılır. Uzamsal yeteneğin en açık göstergelerinden biridir ve sözel ile sayısal muhakemeden ayrı bir faktördür.","Neden her yanlış seçenek ayna görüntüsü","Her yanlış seçenek, hedef şeklin yansıtılmış hâlidir, farklı bir şekil değil. Bu önemlidir: çeldiriciler sadece başka şekiller olsaydı, her soruyu kareleri sayarak çözebilirdiniz ve görev döndürmeyi değil dikkati ölçerdi. Yansıtılmış bir şekil, aslı düzlemde döndürülerek asla elde edilemez; ayırt etmek için gerçekten zihinde döndürmek gerekir. Kullanılmadan önce her şeklin bakışımsız olduğu denetlenir, çünkü bakışımlı bir şekil kendi ayna görüntüsüyle özdeştir ve tek bir doğru cevabı olmazdı.","Alıştırma işe yarar mı?","Evet, çoğu bilişsel görevden daha fazla. Uzamsal beceri eğitime iyi yanıt verir ve kazanımlar ilgili uzamsal problemlere aktarılır, ilgisiz yeteneklere değil.","Neden 20 şekil?","Puanın tüm aralığı yansıtması için küçük ve büyük dönüşleri kapsayacak kadar, testi yaklaşık altı dakikada tutacak kadar az. Şekiller her denemede yeniden üretilir, dolayısıyla ezberlenecek bir cevap anahtarı yoktur."],
"uk": ["Тест на уявне обертання &#8212; безкоштовний тест просторового мислення | CoreSkillAI","20 просторових задач: яка фігура — та сама форма, лише повернута? Вимірює уявне обертання, ключову просторову здатність. Безкоштовно, без реєстрації, щоразу нові фігури.","Наука про уявне обертання","Уявне обертання — це здатність уявити, як предмет обертається, і оцінити, який він мав би вигляд під новим кутом. Шепард і Мецлер у 1971 році показали, що потрібний час зростає майже лінійно з кутом повороту, тому це вважають свідченням справжнього внутрішнього перетворення, а не здогадки. Це один із найчіткіших показників просторової здатності — чинника, відокремленого від словесного та числового мислення.","Чому кожна хибна відповідь дзеркальна","Кожен неправильний варіант — це відображена цільова фігура, а не інша форма. Це важливо: якби відволікачі були просто іншими фігурами, кожне завдання розв'язувалося б підрахунком клітинок, і тест вимірював би увагу, а не обертання. Відображену фігуру неможливо отримати обертанням оригіналу в площині, тож розрізнити їх можна, лише справді повернувши її подумки. Перед використанням кожну фігуру перевіряють на асиметричність, бо симетрична форма збігається з власним дзеркальним відображенням і не мала б єдиної правильної відповіді.","Чи допомагають тренування?","Так, більше, ніж у більшості когнітивних завдань. Просторова навичка добре піддається тренуванню, а приріст переноситься на споріднені просторові задачі, але не на непов'язані здібності.","Чому 20 фігур?","Достатньо, щоб охопити і малі, і великі повороти, аби бал відображав увесь діапазон, і водночас тест триває близько шести хвилин. Фігури створюються заново щоразу, тож немає чого запам'ятовувати."],
"vi": ["Bài kiểm tra xoay hình trong đầu &#8212; bài kiểm tra tư duy không gian miễn phí | CoreSkillAI","20 câu đố không gian: hình nào là cùng một hình được xoay? Đo khả năng xoay hình trong đầu, một năng lực không gian cốt lõi. Miễn phí, không cần đăng ký, hình mới mỗi lần làm.","Khoa học đằng sau việc xoay hình trong đầu","Xoay hình trong đầu là khả năng hình dung một vật đang quay và phán đoán nó trông ra sao từ góc mới. Shepard và Metzler cho thấy năm 1971 rằng thời gian cần thiết tăng gần như tuyến tính theo góc phải xoay, vì vậy đây được xem là bằng chứng của một phép biến đổi nội tâm thật sự chứ không phải phỏng đoán. Đây là một trong những chỉ dấu rõ nhất của năng lực không gian, một yếu tố tách biệt với tư duy ngôn ngữ và số học.","Vì sao mọi đáp án sai đều là ảnh phản chiếu","Mỗi lựa chọn sai là hình mẫu bị phản chiếu, không phải một hình khác. Điều này quan trọng: nếu các lựa chọn gây nhiễu chỉ là những hình khác, bạn có thể giải mọi câu bằng cách đếm ô, và bài kiểm tra sẽ đo sự chú ý thay vì sự xoay hình. Một hình phản chiếu không bao giờ tạo ra được bằng cách xoay hình gốc trong mặt phẳng, nên muốn phân biệt thì phải thực sự xoay nó trong đầu. Mỗi hình đều được kiểm tra tính bất đối xứng trước khi dùng, vì hình đối xứng trùng với ảnh phản chiếu của chính nó và sẽ không có một đáp án đúng duy nhất.","Luyện tập có ích không?","Có, nhiều hơn phần lớn các nhiệm vụ nhận thức. Kỹ năng không gian đáp ứng tốt với luyện tập và tiến bộ chuyển sang các bài toán không gian liên quan, nhưng không sang những năng lực không liên quan.","Vì sao là 20 hình?","Đủ để bao quát cả góc xoay nhỏ lẫn lớn nên điểm phản ánh toàn dải, đồng thời giữ bài kiểm tra trong khoảng sáu phút. Hình được dựng mới mỗi lần làm, nên không có đáp án nào để học thuộc."],
"zh": ["心理旋转测验 &#8212; 免费空间推理测验 | CoreSkillAI","20 道空间题目：哪一个图形是同一形状转过来的？测量心理旋转，这是空间能力的核心。免费、无需注册，每次作答都是全新图形。","心理旋转背后的科学","心理旋转是指在脑中想象物体转动，并判断它从新角度看起来是什么样子的能力。谢泼德与梅茨勒在 1971 年发现，所需时间几乎随需要旋转的角度线性增加，因此这被视为脑中确实发生了变换的证据，而不是猜测。它是空间能力最清晰的标志之一，而空间能力是独立于言语与数字推理的一个因素。","为什么错误选项全是镜像","每个错误选项都是目标图形的镜像，而不是别的形状。这很关键：如果干扰项只是别的形状，数一数方格就能做完每道题，测的就成了注意力而非旋转。镜像图形无法通过在平面内旋转原图得到，因此要区分它们，必须真正在脑中把图形转过来。每个图形在使用前都会检查是否不对称，因为对称图形与自身镜像完全相同，那样就不存在唯一正确答案。","练习有用吗","有用，而且比大多数认知任务更明显。空间技能对训练反应良好，收益会迁移到相关的空间问题上，但不会迁移到无关能力。","为什么是 20 道题","足以涵盖小角度和大角度旋转，让分数反映完整范围，同时把测验控制在六分钟左右。每次作答都会重新生成图形，因此没有可以背诵的答案。"],
}


def build(v):
    return ('<h2>%s</h2><p>%s</p><h3>%s</h3><p>%s</p>'
            '<p><strong>%s</strong> %s</p><p><strong>%s</strong> %s</p>') % tuple(v[2:])


BLOCK = re.compile(r'(<section style="max-width:860px[^>]*>).*?(</section>)', re.S)


def main():
    ready = T.ready_langs()
    missing = [l for l in ready if l not in K]
    if missing:
        print('NO TRANSLATIONS FOR:', missing)
        return 1

    n = 0
    for lang in ready:
        v = K[lang]
        if len(v) != 10:
            print('  BAD ENTRY (%s): expected 10 strings, got %d' % (lang, len(v)))
            return 1
        title, desc = v[0], v[1]
        f = 'tests/rotation/index.html' if lang == 'en' else '%s/tests/rotation/index.html' % lang
        if not os.path.isfile(f):
            print('  MISSING PAGE:', f)
            return 1
        h = io.open(f, encoding='utf-8').read()
        h = re.sub(r'<title>[^<]*</title>', '<title>%s</title>' % title, h, count=1)
        for pat in [r'(<meta name="description" content=")[^"]*(")',
                    r'(<meta property="og:description" content=")[^"]*(")',
                    r'(<meta name="twitter:description" content=")[^"]*(")']:
            h = re.sub(pat, lambda m: m.group(1) + desc.replace('"', '&quot;') + m.group(2), h, count=1)
        for pat in [r'(<meta property="og:title" content=")[^"]*(")',
                    r'(<meta name="twitter:title" content=")[^"]*(")']:
            h = re.sub(pat, lambda m: m.group(1) + title.replace('"', '&quot;') + m.group(2), h, count=1)
        if not BLOCK.search(h):
            print('  NO SCIENCE SECTION:', f)
            return 1
        h = BLOCK.sub(lambda m: m.group(1) + build(v) + m.group(2), h, count=1)
        io.open(f, 'w', encoding='utf-8', newline='\n').write(h)
        n += 1
    print('rotation page localised in %d markets' % n)
    return 0


if __name__ == '__main__':
    sys.exit(main())
